#include <stdio.h>
int main(void){double values[]={2,4,6};struct Stats result;if(!stats(values,3,&result)||result.min!=2||result.max!=6||result.mean!=4)return 1;if(stats(values,0,&result))return 2;puts("2 contratti verificati");return 0;}

