from decimal import Decimal,ROUND_HALF_UP
def quote(price:Decimal,quantity:int,discount:Decimal):
    if price<0 or quantity<1 or not 0<=discount<=100: raise ValueError('Valori invalidi')
    return (price*quantity*(1-discount/100)).quantize(Decimal('.01'),rounding=ROUND_HALF_UP)

