import org.springframework.web.server.ResponseStatusException;
import org.springframework.beans.factory.annotation.*;
import org.springframework.stereotype.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
@RestController
public class DemoController {
private final org.springframework.jdbc.core.JdbcTemplate jdbc;private final org.springframework.transaction.support.TransactionTemplate tx;public DemoController(org.springframework.jdbc.core.JdbcTemplate jdbc,org.springframework.transaction.PlatformTransactionManager manager){this.jdbc=jdbc;this.tx=new org.springframework.transaction.support.TransactionTemplate(manager);}@PostMapping("/reserve")public Map<String,Integer> reserve(@RequestParam("n")int n){if(n<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST);Integer remaining=tx.execute(status->{int changed=jdbc.update("UPDATE inventory SET qty=qty-? WHERE id=1 AND qty>=?",n,n);if(changed!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"Stock insufficiente");return jdbc.queryForObject("SELECT qty FROM inventory WHERE id=1",Integer.class);});return Map.of("qty",remaining);}
}

