@RestController
public class DemoController {
private final TaskService service;public DemoController(TaskService service){this.service=service;}public record Input(@NotBlank String title){}@GetMapping("/tasks")public List<TaskService.Task> list(){return service.list();}@PostMapping("/tasks")public ResponseEntity<TaskService.Task> add(@Valid @RequestBody Input input){var task=service.add(input.title());return ResponseEntity.created(URI.create("/tasks/"+task.id())).body(task);}
}

package it.atlas;
import java.util.*;import org.springframework.stereotype.Service;
@Service public class TaskService{public record Task(long id,String title){}private final List<Task> tasks=new ArrayList<>();private long next=1;public synchronized List<Task> list(){return List.copyOf(tasks);}public synchronized Task add(String title){var clean=title.trim();if(clean.isEmpty())throw new IllegalArgumentException("Titolo vuoto");var task=new Task(next++,clean);tasks.add(task);return task;}}

